  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices turned ultracold atoms into controllable many-body systems, enabling direct study of fundamental quantum phases and dynamics. This is a major experimental and conceptual advance.",
        "attribution": "Bloch and Greiner established landmark experimental demonstrations; Zoller provided foundational theory for quantum simulation. The candidate's broad framing makes precise credit boundaries difficult.",
        "maturity": "The platform has been independently developed and extended over decades, with a substantial body of reproduced results.",
        "uncertainties": [
          "The field's breadth complicates defining a single discovery and allocating credit among its many contributors."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combine exceptional precision with control of atomic motion and interactions, opening new tests of fundamental physics as well as timekeeping.",
        "attribution": "Katori and Ye independently established the leading clock approaches and drove their development. The two-person attribution is unusually clear for a sustained experimental advance.",
        "maturity": "The clocks have been repeatedly demonstrated and improved by multiple laboratories; their precision and reliability are well established.",
        "uncertainties": [
          "The committee would need to judge whether the achievement is best framed as a fundamental advance in precision measurement or primarily as metrology."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "The trapped-ion proposal and its experimental realization established a concrete route to quantum computation and control of individual quantum systems.",
        "attribution": "Cirac and Zoller supplied the influential theoretical proposal; Blatt led pioneering experimental demonstrations. This captures the central theory–experiment link, though the area has many important contributors.",
        "maturity": "The basic control methods have been reproduced widely and developed into increasingly capable systems over several decades.",
        "uncertainties": [
          "It remains a judgment whether the prize should recognize the foundational method now or wait for a clearer demonstration of a distinctive scientific outcome from computation."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation offers a powerful account of the early universe and a framework connecting quantum fluctuations to cosmic structure. If established, its explanatory reach is extraordinary.",
        "attribution": "Guth introduced the seminal inflationary idea; Linde developed influential models, and Mukhanov made key contributions to the theory of density perturbations. Credit depends on which aspect is recognized.",
        "maturity": "The framework has been developed in detail and confronted with precise cosmological observations, but its defining mechanism has not been directly identified.",
        "uncertainties": [
          "There is no unique observational signature that establishes inflation over all alternatives.",
          "The diversity of inflationary models makes the claim and its attribution difficult to delimit."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how fragile quantum information could be protected in principle and made scalable quantum computation physically conceivable.",
        "attribution": "Shor and Steane independently developed seminal error-correcting codes, while Kitaev established deep topological ideas for fault-tolerant quantum computation. The candidate groups distinct but complementary advances.",
        "maturity": "The principles have been repeatedly implemented and improved, though large-scale fault-tolerant computation remains an active goal.",
        "uncertainties": [
          "The named contributions do not constitute one sharply bounded discovery, and it is unclear which should anchor the prize."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics brought cavity quantum optics into the solid-state domain and made strong, controllable light–matter coupling possible with engineered circuits.",
        "attribution": "Blais established the theoretical framework; Wallraff and Schoelkopf led central experimental demonstrations and development. The candidate reflects a strong theory–experiment partnership.",
        "maturity": "The core effects have been replicated across groups and underpin a mature, rapidly advancing research platform.",
        "uncertainties": [
          "The boundary between this discovery and the wider development of superconducting quantum circuits is not sharp."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precision full-sky measurements transformed cosmology by tightly constraining the universe's age, composition, geometry, and early conditions.",
        "attribution": "Bennett and Page led the experimental mission and its analysis; Spergel made a central theoretical contribution to interpreting the results. Team scale and mission history complicate individual credit.",
        "maturity": "The measurements were independently checked and strengthened by later observations, and their cosmological conclusions are deeply embedded in the field.",
        "uncertainties": [
          "It is difficult to distinguish WMAP's contribution from the broader sequence of CMB experiments and the later precision results from Planck."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B021",
      "proposed_laureates": [
        "David DeMille",
        "John M. Doyle",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold molecules create access to rich internal structure and controlled molecular collisions, enabling new tests of quantum dynamics and fundamental interactions.",
        "attribution": "DeMille, Doyle, and Ye made major contributions to producing, cooling, and controlling molecules at ultralow temperatures, though these are distinct lines of work rather than a single joint discovery.",
        "maturity": "The field has advanced considerably, but many applications and scientific opportunities remain under active development.",
        "uncertainties": [
          "The candidate combines different techniques and research programs, making the prize claim and division of credit broad."
        ]
      }
    }
  ]
}
